from sympy import isprime, sqrt, floor

def f(k, n):
    return k*k + k + n

# Test: for each n from 2 to 200, check the theorem
for n in range(2, 300):
    bound = int(floor(sqrt(n/3)))
    # hypothesis: f(k) prime for 0 <= k <= bound
    hyp = all(isprime(f(k, n)) for k in range(0, bound+1))
    # conclusion: f(k) prime for 0 <= k <= n-2
    concl = all(isprime(f(k, n)) for k in range(0, n-1))
    if hyp and not concl:
        print(f"COUNTEREXAMPLE: n={n}, bound={bound}")
        for k in range(0, n-1):
            if not isprime(f(k,n)):
                print(f"  f({k}) = {f(k,n)} composite, k <= sqrt(n/3)? {k <= bound}")
                break
    if not hyp and concl:
        print(f"UNEXPECTED: n={n}, hyp fails but concl holds")

print("Done checking n=2..299")

# Also verify the key lemma: if f(k0) composite for smallest k0 in {0,...,n-2}, then k0 <= sqrt(n/3)
for n in range(2, 500):
    bound = float(sqrt(n/3))
    k0 = None
    for k in range(0, n-1):
        if not isprime(f(k, n)):
            k0 = k
            break
    if k0 is not None:
        if k0 > bound:
            print(f"LEMMA FAILS: n={n}, k0={k0}, sqrt(n/3)={bound:.4f}")

print("Done checking lemma for n=2..499")
